# -*- coding: utf-8 -*-
# Bổ sung lý thuyết: MORE[unit] = danh sách (theo thứ tự phần) các đoạn văn thêm vào cuối mỗi phần
MORE={
'w1':[
 ['Khái niệm: trình duyệt (web browser) là phần mềm cho phép truy cập, hiển thị trang web; máy chủ web (web server) là máy tính lưu trữ website và trả lời yêu cầu từ trình duyệt; địa chỉ trang web (URL) xác định tài nguyên cần truy cập; DNS là dịch vụ chuyển tên miền thành địa chỉ IP.','Quy trình: (1) nhập URL; (2) DNS trả về địa chỉ IP của máy chủ; (3) trình duyệt gửi yêu cầu HTTP/HTTPS; (4) máy chủ gửi lại tệp HTML; (5) trình duyệt đọc HTML, tiếp tục yêu cầu các tệp đi kèm (CSS, ảnh, tập lệnh) rồi hiển thị trang.','HTTPS giống HTTP nhưng được mã hoá, nên người nghe lén trên đường truyền không đọc được nội dung. Vì thế trang cần đăng nhập hoặc thanh toán phải dùng HTTPS.'],
 ['Một tài liệu HTML tối thiểu gồm <!DOCTYPE html> (khai báo phiên bản HTML5), thẻ <html> bao toàn bộ, trong đó có <head> và <body>. Trình duyệt chỉ hiển thị nội dung trong <body>; riêng <title> trong <head> hiện lên thanh tab.','Các thẻ văn bản hay gặp: h1 đến h6 (tiêu đề, h1 lớn nhất), p (đoạn văn), br (xuống dòng, thẻ rỗng), b hoặc strong (đậm), i hoặc em (nghiêng), hr (đường kẻ ngang). Khoảng trắng và xuống dòng nhiều lần trong mã HTML chỉ được hiểu là MỘT dấu cách, muốn xuống dòng phải dùng br hoặc p.','Khi lồng thẻ phải đóng đúng thứ tự: <b><i>chữ</i></b> đúng, còn <b><i>chữ</b></i> là sai vì thẻ mở sau phải đóng trước.'],
 ['Có hai kiểu địa chỉ trong href và src. Đường dẫn tương đối chỉ nói vị trí so với trang hiện tại (ví dụ images/logo.png), dùng cho tệp nằm trong cùng website. Đường dẫn tuyệt đối là địa chỉ đầy đủ có https://, dùng để trỏ ra website khác.','Thuộc tính của thẻ nằm trong thẻ mở và có dạng tên="giá trị". Với video, thuộc tính controls hiện nút phát, tạm dừng, âm lượng; autoplay tự chạy; loop lặp lại. Văn bản viết giữa <video>…</video> chỉ hiện khi trình duyệt không hỗ trợ thẻ này. Với iframe, src là địa chỉ trang cần nhúng, width và height là kích thước khung.']],
'w2':[
 ['Bảng được xây theo từng hàng: mỗi hàng là một thẻ tr, trong hàng có các ô td (dữ liệu) hoặc th (tiêu đề cột, mặc định đậm và căn giữa). Số cột của bảng do hàng nhiều ô nhất quyết định. Không có thẻ "cột" riêng: cột chỉ là các ô cùng vị trí trong các hàng.','Danh sách có thứ tự ol hiển thị 1, 2, 3…; muốn đổi kiểu đánh số dùng thuộc tính type (a, A, i, I). Danh sách lồng nhau được: đặt một ul hoặc ol bên TRONG một thẻ li.'],
 ['Cách làm chắc chắn: vẽ lưới hàng × cột trên giấy, tô các ô bị gộp, rồi viết thẻ td cho từng ô còn lại theo từng hàng, từ trái sang phải.','Ví dụ bảng 3 cột, hàng 1 có một ô colspan="3" thì hàng 1 chỉ viết 1 thẻ td. Nếu hàng 2 có một ô rowspan="2" ở cột 1, thì hàng 3 chỉ cần 2 thẻ td vì cột 1 của hàng 3 đã bị ô phía trên chiếm. Tổng số "ô lưới" mỗi hàng luôn bằng số cột, kể cả ô bị chiếm.'],
 ['Phần tử input có nhiều kiểu qua thuộc tính type: text, password (che kí tự), email, number, checkbox (chọn nhiều), radio (chọn một trong nhóm cùng name), submit (nút gửi), reset (xoá về ban đầu). Danh sách thả xuống dùng select chứa các option; ô nhập nhiều dòng dùng textarea.','Thuộc tính action của form chỉ nơi nhận dữ liệu, method chỉ cách gửi: GET đưa dữ liệu lên thanh địa chỉ (ai cũng thấy, chỉ dùng cho tìm kiếm), POST gửi trong phần thân (dùng cho mật khẩu, dữ liệu quan trọng). Dữ liệu chỉ được gửi khi bấm nút submit (hoặc nhấn Enter trong ô nhập). Các ô không có name thì không được gửi.']],
'w3':[
 ['Trong thực tế người ta ưu tiên tệp .css ngoài vì: một tệp dùng cho cả website, trình duyệt lưu lại (cache) nên các trang sau tải nhanh hơn, và mã HTML sạch hơn. Style trong thẻ chỉ nên dùng khi cần ghi đè cho đúng một phần tử.'],
 ['Cú pháp một quy tắc CSS: bộ chọn { thuộc tính: giá trị; thuộc tính: giá trị; }. Ví dụ p { color: red; } nghĩa là mọi thẻ p có chữ màu đỏ. Bộ chọn trả lời câu hỏi "áp dụng cho phần tử nào?", phần trong dấu { } trả lời "áp dụng kiểu gì?".','Ví dụ đọc từ phải sang trái: ul li a nghĩa là "thẻ a nằm trong li nằm trong ul"; ul > li nghĩa là li là con TRỰC TIẾP của ul; h2 + p nghĩa là chỉ đoạn p đứng NGAY sau h2. Dấu phẩy chỉ là "hoặc": h1, h2 áp dụng cho cả hai.','Lớp giả chọn phần tử theo TRẠNG THÁI hoặc VỊ TRÍ (a:hover khi rê chuột, li:first-child là li đầu tiên của cha, input:focus khi đang nhập); phần tử giả chọn một PHẦN của phần tử (p::first-letter chữ cái đầu, p::first-line dòng đầu, ::before và ::after chèn nội dung).'],
 ['Nhận xét: chỉ đoạn 1 đổi màu vì đoạn 2 nằm trong span, không phải con trực tiếp của div. Muốn chọn cả hai phải dùng "div p" (có dấu cách, chọn mọi cấp).'],
 ['Định nghĩa: kế thừa là cơ chế phần tử con tự nhận giá trị của một số thuộc tính từ phần tử cha khi không có quy tắc riêng. Ví dụ đặt font-family cho body thì các phần tử bên trong đều dùng phông đó. Thuộc tính kế thừa: color, font-*, text-align, line-height. Thuộc tính không kế thừa: border, margin, padding, background, width.','Muốn ép con thừa kế thuộc tính vốn không kế thừa, dùng giá trị inherit, ví dụ border: inherit.']],
'w4':[
 ['Thứ tự này là "bộ lọc nhiều tầng": quy tắc nào thắng ở tầng cao hơn thì khỏi xét tầng thấp. Ví dụ quy tắc có !important luôn thắng quy tắc không có, dù bộ chọn của quy tắc kia mạnh đến đâu. Kế thừa yếu nhất: nếu chính phần tử đó có bất kì quy tắc nào cho thuộc tính ấy, giá trị kế thừa từ cha bị bỏ qua.'],
 ['Để tính, hãy đếm ba loại thành phần trong bộ chọn: số id (a), số lớp + thuộc tính + lớp giả (b), số thẻ + phần tử giả (c), rồi lấy 100a + 10b + c. Ví dụ "div #menu .item a:hover" có 1 id, 2 (lớp .item và lớp giả :hover), 2 thẻ (div, a) nên là 100 + 20 + 2 = 122.','Khi điểm bằng nhau thì quy tắc viết SAU (ở dưới) thắng. Vì vậy thứ tự khai báo trong tệp CSS quan trọng.'],
 ['Cách nhớ: !important > style trong thẻ > id > lớp > thẻ. Khi làm bài, ghi điểm bên cạnh từng quy tắc rồi so sánh, đừng đoán bằng mắt.']],
'w5':[
 ['Định nghĩa: mô hình hộp (box model) coi mỗi phần tử HTML là một hộp chữ nhật gồm bốn vùng: content (nội dung), padding (đệm, khoảng cách từ nội dung đến viền), border (viền) và margin (lề, khoảng cách từ viền đến phần tử khác).','Dùng content-box nên khi đặt width: 300px mà thêm padding và border thì hộp "to ra" hơn 300px, dễ làm vỡ bố cục. Vì vậy người ta hay đặt * { box-sizing: border-box } để width luôn là tổng kích thước nhìn thấy.'],
 ['Lề dọc gộp nhau chỉ xảy ra với margin trên/dưới của các khối liền kề theo chiều dọc; margin trái/phải không gộp. Trong Flexbox, margin cũng không gộp.'],
 ['Định nghĩa: Flexbox là mô hình bố cục một chiều; phần tử có display: flex là vùng chứa (flex container), các phần tử con trực tiếp là mục (flex item). Thuộc tính của vùng chứa: flex-direction (hướng trục chính), justify-content (căn theo trục chính: flex-start, center, flex-end, space-between, space-around), align-items (căn theo trục phụ), flex-wrap (cho phép xuống dòng).','Tính chất: khi flex-direction: column thì trục chính là chiều dọc, nên justify-content căn theo chiều dọc còn align-items căn theo chiều ngang. space-between đặt mục đầu và mục cuối sát hai mép, chia đều khoảng trống ở giữa.'],
 ['Phần tử có position: absolute được "lấy ra khỏi dòng chảy" nên các phần tử khác coi như nó không tồn tại. Nó định vị theo phần tử tổ tiên gần nhất có position khác static (thường đặt relative cho cha để làm mốc).']],
'w6':[
 ['Mỗi bước có việc cụ thể. Bước xác định mục đích trả lời "website để làm gì, ai dùng?". Bước phác thảo vẽ sơ đồ trang (trang chủ, giới thiệu, liên hệ…) và menu để người xem không bị lạc. Bước thiết kế chọn bảng màu, phông chữ, bố cục. Sau đó mới viết HTML/CSS.'],
 ['Xuất bản nghĩa là đưa các tệp lên máy chủ web (có tên miền) để mọi người truy cập. Sau khi xuất bản vẫn phải bảo trì: cập nhật nội dung, sửa liên kết hỏng, sao lưu, bảo mật.','Thiết kế đáp ứng (responsive) làm cho trang hiển thị tốt trên cả điện thoại lẫn máy tính, thường nhờ @media và đơn vị tương đối.']],
'p1':[
 ['Cách nhớ ý nghĩa: % cho phần dư, // cho phần nguyên của phép chia. Ví dụ 17 chia 5 được 3 dư 2, nên 17//5 = 3 và 17%5 = 2. Dùng % rất nhiều để kiểm tra chẵn lẻ (n % 2 == 0), chia hết (n % k == 0) hoặc lấy chữ số cuối (n % 10).','Phép ** kết hợp từ PHẢI sang trái: 2**3**2 = 2**(3**2) = 2**9 = 512, chứ không phải (2**3)**2 = 64. Phép so sánh nối chuỗi như 1 < 2 < 3 nghĩa là (1<2) và (2<3), cho True.'],
 ['Bốn kiểu cơ bản: int (số nguyên), float (số thực, có dấu chấm), str (xâu kí tự), bool (True/False). Hàm type() cho biết kiểu. Phép / luôn cho float, kể cả 8/4 = 2.0.','Nhập hai số rồi cộng: nếu viết a = input(); b = input(); print(a+b) với 5 và 3 sẽ ra "53" vì cộng hai xâu là NỐI xâu. Phải viết a = int(input()). Đây là lỗi rất hay gặp.']],
'p2':[
 ['Cấu trúc rẽ nhánh if/elif/else chỉ chạy MỘT nhánh đầu tiên có điều kiện đúng, các nhánh sau bị bỏ qua dù cũng đúng. Vì vậy thứ tự các điều kiện rất quan trọng: nên xét trường hợp hẹp trước.','Vòng for dùng khi biết trước số lần lặp; while dùng khi lặp đến khi điều kiện sai (không biết trước số lần). Với while, nhớ cập nhật biến điều kiện, nếu không sẽ lặp vô hạn.','Ví dụ: range(1, 20, 4) cho 1, 5, 9, 13, 17, tức 5 phần tử, đúng với (20−1)/4 = 4,75 làm tròn lên thành 5. range(5, 0, −2) cho 5, 3, 1 (bước âm thì đếm lùi, dừng trước 0).'],
 ['Vòng lồng ví dụ: vòng ngoài i = 1..4, vòng trong lặp i lần thì tổng số lần là 1+2+3+4 = 10. Khi vòng trong có break, break chỉ thoát vòng trong, vòng ngoài vẫn tiếp tục.'],
 ['Một bảng trace có thể có các cột: lượt, s, n, điều kiện n>0. Lượt 1: s=5, n=3; lượt 2: s=8, n=1; lượt 3: s=9, n=−1; điều kiện sai nên dừng. In ra 9 và −1.']],
'p3':[
 ['Chỉ số âm: s[-1] là kí tự cuối, s[-2] là kí tự kề cuối. Với xâu độ dài n, chỉ số hợp lệ là từ −n đến n−1; ngoài khoảng đó sẽ báo IndexError. Riêng cắt lát thì không báo lỗi mà trả về phần có được.','Cắt lát s[a:b] lấy các vị trí a, a+1, …, b−1 (không có b). Bước âm đảo chiều: s[::-1] là xâu đảo ngược. Hãy tự vẽ dãy chỉ số bên dưới từng kí tự trước khi cắt.'],
 ['Danh sách có thể thay đổi tại chỗ bằng append, insert, pop, remove, sort. Phép gán b = a KHÔNG tạo bản sao mà chỉ thêm một tên khác cho cùng danh sách. Muốn bản sao độc lập dùng a.copy() hoặc a[:]. Với danh sách chứa danh sách (ma trận), cần sao chép sâu mới độc lập hoàn toàn.'],
 ['Tạo ma trận n×n đúng cách: [[0]*n for _ in range(n)]. Cách sai [[0]*n]*n tạo n hàng cùng trỏ một danh sách, sửa một hàng thì mọi hàng đổi theo.','Duyệt hai vòng lồng: vòng ngoài là hàng i, vòng trong là cột j. Tổng một hàng: sum(m[i]); tổng một cột: sum(m[i][j] for i in range(n)).']],
'p4':[
 ['Quy tắc LEGB đơn giản: Python tìm tên biến từ trong hàm ra ngoài (cục bộ rồi toàn cục). Gán giá trị cho một tên bên trong hàm sẽ tạo biến cục bộ MỚI, che biến cùng tên bên ngoài. Chỉ đọc biến toàn cục thì không cần khai báo; muốn gán lại phải viết global tên_biến.','Hàm không có lệnh return trả về None. Đối số truyền vào là tham chiếu, nên list bị sửa trong hàm cũng đổi ở bên ngoài, còn số và xâu thì không.'],
 ['Phân biệt rõ: lỗi cú pháp (SyntaxError) báo ngay khi chạy; lỗi chạy xuất hiện lúc thực thi, ví dụ chia cho 0, chuyển "abc" thành số, truy cập chỉ số vượt mức; lỗi logic không báo gì nhưng kết quả sai, chỉ phát hiện bằng kiểm thử.','try/except bắt đúng loại lỗi cần xử lí, nên ghi rõ tên (ví dụ except ValueError) thay vì bắt mọi lỗi. Khối finally luôn chạy dù có lỗi hay không, thường dùng để đóng tệp, dọn dẹp.'],
 ['Ví dụ hàm tính trung bình của danh sách: ca thông thường [2,4,6]; ca biên danh sách có một phần tử [5] và danh sách rỗng [] (phát hiện lỗi chia cho 0); ca bất thường như phần tử âm. Kiểm thử kĩ ở các ca biên là cách bắt lỗi hiệu quả nhất.']],
'p5':[
 ['Vì sao bỏ hằng số? Vì khi n rất lớn, hằng số không còn quyết định. Chương trình 100n bước vẫn là O(n); chương trình n² bước với n = 1 000 000 thì chậm hơn rất nhiều dù hằng số nhỏ. Mỗi lần n tăng gấp 10: O(n) chậm 10 lần, O(n²) chậm 100 lần, O(log n) chỉ chậm thêm vài bước.','Trường hợp tốt nhất, trung bình và xấu nhất có thể khác nhau. Tìm tuần tự: tốt nhất 1 bước (phần tử đầu), xấu nhất n bước, nên nói O(n).'],
 ['Đếm vòng lặp: while n > 1: n //= 2 chạy khoảng log₂n lần (n = 8 chạy 3 lần). Vòng lồng "for j in range(i, n)" cho tổng n + (n−1) + … + 1 = n(n+1)/2, bậc n². Hai vòng nối tiếp (không lồng) cộng lại: O(n) + O(n) vẫn là O(n).']],
'p6':[
 ['Mỗi bước tìm nhị phân loại bỏ một nửa nên 1000 phần tử cần tối đa khoảng 10 lần so sánh, 1 triệu phần tử chỉ khoảng 20 lần. So với tìm tuần tự cần đến 1 triệu lần, nên tìm nhị phân rất mạnh, nhưng chỉ dùng được khi dãy đã sắp. Nếu chưa sắp, mất O(n log n) để sắp xếp trước, chỉ đáng khi tìm nhiều lần.','Chú ý cập nhật đúng: nếu a[m] < x thì lo = m + 1; nếu a[m] > x thì hi = m − 1. Cập nhật sai (lo = m) có thể lặp vô hạn.'],
 ['Sắp xếp chọn luôn thực hiện khoảng n²/2 phép so sánh dù dãy đã sắp, nhưng chỉ đổi chỗ tối đa n−1 lần. Nên ghi lại dãy sau mỗi lượt để theo dõi: dãy [5,2,9,1,7] sau lượt 1 là [1,2,9,5,7] (đổi 5 với 1).'],
 ['Nổi bọt: sau lượt 1, phần tử lớn nhất ở cuối; sau lượt 2, hai phần tử lớn nhất ở cuối… Nếu một lượt không đổi chỗ lần nào thì dãy đã sắp và có thể dừng sớm. Sắp xếp chèn rất nhanh với dãy gần như đã sắp.']],
'p7':[
 ['Mỗi lời gọi hàm được đặt vào ngăn xếp lời gọi; gọi quá sâu thì hết chỗ và gây RecursionError. Để viết đệ quy: (1) nêu trường hợp cơ sở, (2) viết bước đệ quy sao cho bài toán nhỏ hơn và tiến về trường hợp cơ sở.','Với fib(n) = fib(n−1) + fib(n−2), mỗi lời gọi sinh hai lời gọi con nên số lời gọi tăng rất nhanh (fib(5) gọi 15 lần), nhiều phép tính lặp lại. Giải pháp là ghi nhớ kết quả đã tính hoặc dùng vòng lặp.'],
 ['Ba bước chia để trị: chia (tách thành các bài toán con cùng loại, nhỏ hơn), trị (giải từng bài con, thường bằng đệ quy), hợp (ghép kết quả). Tìm nhị phân chỉ giải MỘT nửa; sắp xếp trộn giải cả hai nửa rồi trộn lại, độ phức tạp O(n log n).']],
'p8':[
 ['Định nghĩa: ngăn xếp (stack) là cấu trúc dữ liệu mà phần tử thêm vào sau được lấy ra trước (LIFO), thao tác ở một đầu. Hàng đợi (queue) là cấu trúc dữ liệu mà phần tử thêm vào trước được lấy ra trước (FIFO), thêm ở cuối và lấy ở đầu. Ứng dụng ngăn xếp: hoàn tác, kiểm tra ngoặc cân bằng, lưu lời gọi hàm đệ quy. Ứng dụng hàng đợi: hàng đợi in, xử lí yêu cầu theo thứ tự đến.','Với list Python: ngăn xếp dùng append và pop() (lấy cuối, nhanh); hàng đợi dùng append và pop(0) (lấy đầu). Lấy từ ngăn xếp/hàng đợi rỗng gây lỗi IndexError.']],
'c1':[
 ['Ví dụ: thư viện trường có tệp Excel rời rạc cho từng lớp thì một sách có thể ghi nhiều tên khác nhau, sửa chỗ này quên chỗ kia (dư thừa, mâu thuẫn). Khi dùng một CSDL thư viện dưới sự quản lí của hệ QTCSDL, mọi người cùng truy cập một nguồn, sửa một lần là đúng ở mọi nơi.'],
 ['Hệ QTCSDL có ba nhóm chức năng chính: định nghĩa dữ liệu (tạo bảng, kiểu, ràng buộc), thao tác dữ liệu (thêm, sửa, xoá, truy vấn) và kiểm soát (phân quyền, an toàn, đồng thời, sao lưu). Ví dụ hệ QTCSDL: MySQL, PostgreSQL, SQL Server, Oracle, SQLite.']],
'c2':[
 ['Ví dụ bảng KhachHang(MaKH, Ten) và DonHang(MaDH, MaKH, SoTien). MaKH là khoá chính của KhachHang. Trong DonHang, MaKH là khoá ngoài trỏ về KhachHang: mỗi đơn phải thuộc một khách có thật. Nhờ ràng buộc này dữ liệu không bị "mồ côi".','Khoá chính có thể gồm nhiều cột (khoá phức hợp). Một bảng chỉ có một khoá chính nhưng có thể có nhiều khoá ngoài.'],
 ['Chọn kiểu đúng giúp tiết kiệm bộ nhớ và kiểm tra dữ liệu: tuổi dùng INTEGER, điểm trung bình dùng số thực, họ tên dùng chuỗi, ngày sinh dùng DATE. Mã số kiểu 0123 phải lưu dạng chuỗi, vì dạng số sẽ mất số 0 đầu.']],
'c3':[
 ['Ví dụ: lọc đơn hàng có SoTien > 20 trước khi nhóm (WHERE), rồi mới giữ các khách có từ 2 đơn trở lên (HAVING COUNT(*) >= 2). Nhầm lẫn thường gặp: viết WHERE COUNT(*) >= 2 sẽ báo lỗi vì lúc xét WHERE chưa có nhóm.'],
 ['Hàm tổng hợp gom nhiều dòng thành MỘT giá trị. AVG bỏ qua giá trị NULL khi tính trung bình. COUNT(*) đếm cả dòng có NULL, còn COUNT(MaKH) không đếm dòng có MaKH là NULL. Để đếm số khách khác nhau, dùng COUNT(DISTINCT MaKH).'],
 ['Định nghĩa: GROUP BY gom các dòng có cùng giá trị ở cột chỉ định thành một nhóm; mỗi nhóm cho ra một dòng kết quả. Tính chất: khi có GROUP BY, mỗi cột trong SELECT phải là cột nhóm hoặc nằm trong hàm tổng hợp. ORDER BY … ASC/DESC sắp xếp kết quả tăng/giảm, đặt ở cuối câu lệnh.']],
'c4':[
 ['Xét bảng kết quả bên dưới: khách "Dũng" chưa có đơn nên với INNER JOIN không xuất hiện, còn LEFT JOIN vẫn có dòng Dũng với MaDH và SoTien là NULL. Để tìm khách CHƯA có đơn: LEFT JOIN rồi lọc WHERE D.MaDH IS NULL (so sánh với NULL phải dùng IS NULL, không dùng = NULL).','Số dòng INNER JOIN bằng số cặp khớp: khách có 3 đơn cho 3 dòng, khách có 0 đơn cho 0 dòng.'],
 ['Truy vấn con trả về một giá trị thì so sánh bằng =, >, <; trả về nhiều giá trị thì dùng IN hoặc NOT IN. Ví dụ tìm khách có đơn lớn hơn mức trung bình: WHERE SoTien > (SELECT AVG(SoTien) FROM DonHang). Cách đọc: chạy phần trong ngoặc trước, lấy kết quả thay vào truy vấn ngoài.']],
'c5':[
 ['Phân quyền theo vai trò: người quản trị được mọi quyền; nhân viên bán hàng chỉ SELECT và INSERT đơn hàng; kế toán chỉ SELECT. Nếu tài khoản bị lộ, thiệt hại giới hạn trong phạm vi quyền đó.','Sao lưu định kì giúp khôi phục khi mất dữ liệu do lỗi hoặc tấn công. Mã hoá bảo vệ dữ liệu nhạy cảm như mật khẩu, thông tin cá nhân. Nhật kí ghi lại ai làm gì, để truy vết khi có sự cố.']],
'm1':[
 ['Cách phân biệt nhanh: switch chỉ chuyển tiếp dữ liệu giữa các thiết bị trong CÙNG mạng; router nối NHIỀU mạng và quyết định gói đi đường nào (nên có địa chỉ IP ở mỗi cổng); modem biến đổi tín hiệu giữa đường truyền của nhà mạng và tín hiệu số của máy tính; access point cho thiết bị không dây tham gia mạng có dây. Ở gia đình, một thiết bị thường gộp cả modem, router và Wi-Fi.'],
 ['Hình sao là cấu trúc phổ biến nhất ở mạng LAN hiện nay: dễ thêm bớt máy, một máy hỏng không ảnh hưởng, nhưng thiết bị trung tâm (switch) hỏng thì cả mạng ngừng. Hình đường thẳng (bus) dùng một dây chung nên đứt dây là hỏng mạng. Hình vòng: dữ liệu đi theo một chiều quanh vòng.'],
 ['Định nghĩa: mô hình phân tầng chia chức năng truyền thông thành các tầng; mỗi tầng chỉ sử dụng dịch vụ của tầng kề dưới và cung cấp dịch vụ cho tầng kề trên. Tính chất: các tầng độc lập tương đối nên thay đổi công nghệ ở một tầng (ví dụ Wi-Fi thay cho cáp) không làm thay đổi các tầng khác.']],
'm2':[
 ['Mỗi giao thức là một bộ quy ước mà hai máy phải cùng tuân thủ để hiểu nhau. Phân biệt: TCP đảm bảo dữ liệu đến đủ, đúng thứ tự (chậm hơn nhưng tin cậy), còn UDP gửi nhanh, không đảm bảo (dùng cho video trực tiếp, trò chơi). IP lo địa chỉ và chọn đường cho từng gói tin.','Với thư điện tử: SMTP dùng để GỬI thư; POP3 hoặc IMAP dùng để NHẬN thư (IMAP giữ thư trên máy chủ, đọc được từ nhiều thiết bị).','Cổng thường gặp: HTTP 80, HTTPS 443. Khi bạn gõ tên miền, máy hỏi DNS lấy địa chỉ IP, sau đó trình duyệt kết nối tới cổng 443 của máy chủ đó.']],
'm3':[
 ['Địa chỉ IPv4 như 192.168.1.10 gồm 32 bit chia 4 nhóm 8 bit. Mặt nạ mạng con 255.255.255.0 tương đương /24: 24 bit đầu cố định cho phần mạng. Hai máy cùng mạng khi phần mạng của chúng bằng nhau; khác mạng thì phải qua router.','Ví dụ /26: có 32−26 = 6 bit cho phần máy, nên có 2⁶ = 64 địa chỉ, trừ 2 (một địa chỉ đại diện mạng, một địa chỉ quảng bá) còn 62 máy dùng được. Với /24: 2⁸−2 = 254 máy.','Khi chia mạng 192.168.1.0/24 thành 4 mạng con, mượn thêm 2 bit từ phần máy, được /26, mỗi mạng con có 62 máy dùng được. Dải 192.168.x.x, 10.x.x.x là địa chỉ riêng, chỉ dùng trong mạng nội bộ.']],
'm4':[
 ['Khi chia sẻ thư mục trong LAN, chỉ cấp quyền "chỉ đọc" cho người chỉ cần xem; quyền "đọc và ghi" cho người cần sửa. Mỗi quyền thừa là một lỗ hổng.'],
 ['Phishing là mạo danh trang web hoặc thư của nơi đáng tin để lừa lấy mật khẩu. Dấu hiệu: địa chỉ lạ, yêu cầu gấp, lỗi chính tả. Mật khẩu mạnh dài, có chữ hoa, thường, số và kí hiệu, và không dùng chung giữa các tài khoản. Xác thực hai bước giúp an toàn kể cả khi lộ mật khẩu.']],
'a1':[
 ['Các đặc trưng thường nêu của AI: khả năng học, suy luận, nhận biết (thị giác, ngôn ngữ), tương tác, và tự thích nghi. Ví dụ phân biệt: máy giặt hẹn giờ là tự động hoá vì chỉ làm theo quy tắc; ứng dụng gợi ý bài hát học từ thói quen nghe của bạn là AI vì thay đổi theo dữ liệu.','Ứng dụng AI theo lĩnh vực: y tế (đọc ảnh chụp X-quang), giáo dục (gợi ý bài học phù hợp), giao thông (xe tự lái, dự báo ùn tắc), nông nghiệp (nhận biết sâu bệnh qua ảnh).'],
 ['Rủi ro cần nhớ: thiên kiến (dữ liệu huấn luyện lệch thì kết quả lệch), thông tin sai nhưng trình bày rất tự tin, deepfake, lộ dữ liệu cá nhân nếu nhập vào hệ thống không an toàn, phụ thuộc quá mức. Cách dùng có trách nhiệm: kiểm chứng bằng nguồn tin cậy, không nhập thông tin riêng tư, ghi rõ phần nội dung do AI tạo.']],
'a2':[
 ['Ví dụ có giám sát: có tập ảnh đã gán nhãn "mèo" và "chó", mô hình học để phân loại ảnh mới (phân loại); có dữ liệu diện tích và giá nhà, mô hình học để dự đoán giá (hồi quy). Ví dụ không giám sát: gom khách hàng thành nhóm theo thói quen mua sắm khi chưa biết trước nhóm nào (phân cụm).'],
 ['Ví dụ trong hình: k = 4, trong 4 điểm gần nhất có 3 điểm xanh lá và 1 điểm đỏ, vậy dự đoán là xanh lá (đa số). Chọn k lẻ giúp tránh hoà phiếu khi có hai nhãn. k quá nhỏ dễ nhạy với nhiễu; k quá lớn làm mờ ranh giới giữa các nhãn. k-NN cần dữ liệu có thang đo tương đương, nên thường chuẩn hoá trước.']],
'a3':[
 ['Nguyên tắc: dữ liệu kiểm tra không được dùng trong quá trình huấn luyện để kết quả đánh giá khách quan. Tỉ lệ chia thường gặp là 80% huấn luyện, 20% kiểm tra.'],
 ['Độ chính xác = số dự đoán đúng / tổng số mẫu. Với ví dụ TP = 40, TN = 45, FP = 5, FN = 10 thì (40+45)/100 = 0,85. Quá khớp nhận ra khi độ chính xác trên tập huấn luyện rất cao (ví dụ 99%) nhưng trên tập kiểm tra thấp (ví dụ 70%). Cách giảm: thêm dữ liệu, đơn giản hoá mô hình, dừng huấn luyện sớm.']],
'a4':[
 ['Ví dụ làm sạch: cột tuổi có ô trống (xử lí giá trị thiếu: điền giá trị trung bình hoặc loại bỏ), có hai dòng giống hệt (bỏ trùng), có giá trị 250 tuổi (giá trị bất thường). Chuẩn hoá đưa các cột về cùng thang để cột có số lớn không lấn át cột có số nhỏ.','Hệ số tương quan gần +1 nghĩa là hai đại lượng cùng tăng; gần −1 là một tăng một giảm; gần 0 là hầu như không liên quan. Số ca cảm cúm và doanh số kem có thể cùng tăng vào mùa hè nhưng cái này không gây ra cái kia.'],
 ['Mô phỏng có ích khi thí nghiệm thật quá đắt, nguy hiểm hoặc mất nhiều thời gian: mô phỏng va chạm ô tô, lan truyền dịch bệnh, thí nghiệm vật lí ảo. Kết quả mô phỏng chỉ đúng chừng nào mô hình còn phản ánh đúng hệ thống thật.']],
'n1':[
 ['Mỗi nhóm nghề cần kĩ năng khác nhau: lập trình viên (ngôn ngữ lập trình, thuật toán), nhà khoa học dữ liệu (thống kê, học máy), quản trị mạng (thiết bị mạng, giao thức), chuyên gia an toàn thông tin (phát hiện và phòng chống tấn công), thiết kế web hoặc đồ hoạ (mĩ thuật, HTML/CSS). Những năng lực chung: tư duy logic, làm việc nhóm, học liên tục, đọc tài liệu tiếng Anh.']],
'n2':[
 ['Một số tình huống: dùng ảnh, nhạc tải trên mạng vào sản phẩm của mình mà không xin phép hoặc ghi nguồn là vi phạm bản quyền; phần mềm có giấy phép thì chỉ được dùng đúng điều khoản; chia sẻ ảnh của người khác lên mạng khi chưa được đồng ý có thể xâm phạm quyền riêng tư; truy cập tài khoản người khác trái phép là vi phạm pháp luật. Trước khi chia sẻ thông tin, nên kiểm tra nguồn và hậu quả đối với người khác.']],
}

PRE={
'w1':{0:['Định nghĩa: World Wide Web (WWW) là hệ thống các trang web liên kết với nhau qua Internet; mỗi trang được xác định bởi một địa chỉ URL.'],1:['Định nghĩa: HTML (HyperText Markup Language) là ngôn ngữ đánh dấu siêu văn bản dùng để mô tả cấu trúc và nội dung trang web. Phần tử HTML gồm thẻ mở, nội dung và thẻ đóng; thuộc tính cung cấp thông tin bổ sung cho thẻ.']},
'w2':{0:['Định nghĩa: bảng (table) trình bày dữ liệu theo hàng và cột. Danh sách (list) trình bày một dãy mục; có hai loại: không thứ tự (ul) và có thứ tự (ol).'],2:['Định nghĩa: biểu mẫu (form) là thành phần cho phép người dùng nhập dữ liệu và gửi về máy chủ xử lí.']},
'w3':{0:['Định nghĩa: CSS (Cascading Style Sheets) là ngôn ngữ định dạng dùng để mô tả cách hiển thị các phần tử HTML (màu sắc, phông chữ, kích thước, bố cục).'],1:['Định nghĩa: bộ chọn (selector) là biểu thức xác định các phần tử HTML mà quy tắc CSS áp dụng.']},
'w4':{0:['Định nghĩa: khi nhiều quy tắc CSS cùng đặt giá trị cho một thuộc tính của một phần tử, trình duyệt phải chọn một quy tắc; việc chọn dựa trên mức ưu tiên (độ đặc hiệu của bộ chọn và thứ tự khai báo).']},
'w5':{0:['Phân biệt: padding là khoảng cách giữa nội dung và viền, nằm trong viền, có màu nền của phần tử; margin là khoảng cách giữa viền và phần tử bên ngoài, luôn trong suốt.']},
'p1':{0:['Định nghĩa: biểu thức là sự kết hợp của hằng, biến, toán tử và lời gọi hàm, khi tính toán cho ra một giá trị. Toán tử số học: +, -, *, /, //, %, **; toán tử so sánh: ==, !=, <, >, <=, >=; toán tử logic: and, or, not.'],1:['Định nghĩa: kiểu dữ liệu xác định tập giá trị và các phép toán trên giá trị đó. Python có các kiểu cơ bản int, float, str, bool.']},
'p2':{0:['Định nghĩa: cấu trúc rẽ nhánh thực hiện công việc tuỳ theo điều kiện; cấu trúc lặp thực hiện lặp lại một nhóm lệnh. Lặp với số lần biết trước dùng for, lặp khi điều kiện còn đúng dùng while.']},
'p3':{0:['Định nghĩa: xâu kí tự (str) là dãy các kí tự; danh sách (list) là dãy các phần tử có thể thuộc nhiều kiểu. Cả hai đánh chỉ số từ 0 và hỗ trợ cắt lát. Tính chất: xâu là kiểu dữ liệu bất biến, danh sách là kiểu dữ liệu khả biến.']},
'p4':{0:['Định nghĩa: hàm là một nhóm lệnh có tên, nhận tham số và có thể trả về giá trị. Phạm vi của biến là vùng chương trình mà biến có thể truy cập: biến cục bộ khai báo trong hàm, biến toàn cục khai báo ngoài mọi hàm.']},
'p5':{0:['Định nghĩa: độ phức tạp thời gian của thuật toán là hàm mô tả số phép toán cơ bản thực hiện theo kích thước dữ liệu vào n, thường biểu diễn bằng kí hiệu O(f(n)) (độ phức tạp tiệm cận, chỉ giữ số hạng bậc cao nhất).']},
'p6':{0:['Định nghĩa: tìm kiếm là bài toán xác định vị trí của giá trị cần tìm trong một dãy. Tìm kiếm tuần tự xét lần lượt từng phần tử, độ phức tạp O(n); tìm kiếm nhị phân áp dụng cho dãy đã sắp xếp, độ phức tạp O(log n).']},
'p7':{0:['Định nghĩa: đệ quy là kĩ thuật trong đó hàm gọi lại chính nó để giải bài toán nhỏ hơn cùng dạng. Một hàm đệ quy gồm: điều kiện dừng (trường hợp cơ sở) và phần đệ quy.']},
'c1':{0:['Định nghĩa: cơ sở dữ liệu (CSDL) là tập hợp dữ liệu có cấu trúc, liên quan với nhau, được lưu trữ trên thiết bị nhớ nhằm phục vụ nhiều người dùng. Hệ quản trị CSDL là phần mềm tạo lập, lưu trữ, cập nhật và khai thác CSDL.']},
'c2':{0:['Định nghĩa: khoá chính là thuộc tính (hoặc nhóm thuộc tính) có giá trị duy nhất, không rỗng để phân biệt các bản ghi trong bảng. Khoá ngoài là thuộc tính của bảng này tham chiếu tới khoá chính của bảng khác để liên kết hai bảng.']},
'c3':{0:['Định nghĩa: SQL (Structured Query Language) là ngôn ngữ truy vấn có cấu trúc dùng để định nghĩa, thao tác và truy vấn dữ liệu trong CSDL quan hệ. Truy vấn dữ liệu dùng lệnh SELECT.']},
'c4':{0:['Định nghĩa: phép kết nối (JOIN) ghép các dòng của hai bảng dựa trên điều kiện liên kết (thường là khoá ngoài bằng khoá chính). INNER JOIN chỉ giữ các cặp thoả điều kiện; LEFT JOIN giữ toàn bộ dòng bảng bên trái.']},
'm1':{0:['Định nghĩa: mạng máy tính là tập hợp các máy tính và thiết bị được kết nối với nhau để trao đổi dữ liệu và chia sẻ tài nguyên. Phân loại theo phạm vi: LAN (mạng cục bộ), WAN (mạng diện rộng).']},
'm2':{0:['Định nghĩa: giao thức mạng là tập hợp các quy tắc quy định cách thức trao đổi dữ liệu giữa các thiết bị trong mạng.']},
'm3':{0:['Định nghĩa: địa chỉ IP là số định danh duy nhất của thiết bị trong mạng sử dụng giao thức IP. Mặt nạ mạng con cho biết bao nhiêu bit đầu của địa chỉ là phần mạng.']},
'a1':{0:['Định nghĩa: trí tuệ nhân tạo (AI) là khả năng của máy tính thực hiện những công việc đòi hỏi trí tuệ con người như học tập, suy luận, nhận dạng, ra quyết định.']},
'a2':{0:['Định nghĩa: học máy (Machine Learning) là một nhánh của AI cho phép hệ thống tự học từ dữ liệu để cải thiện kết quả mà không cần lập trình chi tiết từng quy tắc.']},
'a3':{0:['Định nghĩa: dữ liệu huấn luyện dùng để xây dựng mô hình; dữ liệu kiểm tra dùng để đánh giá mô hình trên dữ liệu chưa từng thấy. Quá khớp (overfitting) là hiện tượng mô hình phù hợp rất tốt với dữ liệu huấn luyện nhưng kém trên dữ liệu mới.']},
'a4':{0:['Định nghĩa: khoa học dữ liệu là lĩnh vực thu thập, xử lí, phân tích dữ liệu để rút ra thông tin và tri thức. Làm sạch dữ liệu là phát hiện và xử lí giá trị thiếu, trùng lặp, sai lệch.']},
'n1':{0:['Nhóm nghề trong ngành Công nghệ thông tin gồm: phát triển phần mềm, khoa học dữ liệu và AI, mạng máy tính, an toàn thông tin, thiết kế web và đồ hoạ, quản trị hệ thống.']},
'n2':{0:['Định nghĩa: bản quyền (quyền tác giả) là quyền của tác giả đối với tác phẩm do mình sáng tạo. Phần mềm có giấy phép chỉ được sử dụng theo điều khoản đã quy định. Dữ liệu cá nhân là thông tin gắn với một người cụ thể, cần được bảo vệ.']},
}
